import{_ as o,p as a,q as s,s as e,R as n,t as c,n as d}from"./framework-e1bed10d.js";const r={},_=e("h1",{id:"第六章-核算与会计引擎-九-本章小结",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#第六章-核算与会计引擎-九-本章小结","aria-hidden":"true"},"#"),n(" 第六章 核算与会计引擎-（九）本章小结")],-1),l={href:"https://mp.weixin.qq.com/s?__biz=MzIzNzQ5NjU5NQ==&mid=2247485092&idx=1&sn=f26b275857253b1ba49fddad7a46f9ab&chksm=e8c6f6d8dfb17fceb987c3573d2d75c77fe54d6c9ba70dcfeb1503673ff2600229ae0448b3b2",target:"_blank",rel:"noopener noreferrer"},i=e("hr",null,null,-1),h=e("h2",{id:"九、本章小结",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#九、本章小结","aria-hidden":"true"},"#"),n(" 九、本章小结")],-1),f=e("p",null,"这一章把核算与会计引擎讲完了。一句话总结：业务系统回答“发生了什么”，核算系统回答“账上怎么记”，会计引擎是中间的翻译官，交易代码进、分录出，客户账、机构账、总账一层层汇总，日终总分核对兜底。",-1),u=e("p",null,"三个关键认知：第一，借贷记账法是让账“自带解释”的设计，每一笔借，都要有一笔贷回答钱从哪来；第二，权责发生制决定了利息天天计提、挂应收利息；第三，账务的工程纪律还是第五章说的那三件套：幂等、冲正、总分核对，缺一件，账早晚不平。",-1),b=e("h4",{id:"【作者手记】账务不平的那一夜",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#【作者手记】账务不平的那一夜","aria-hidden":"true"},"#"),n(" 【作者手记】账务不平的那一夜")],-1),p=e("p",null,"账务知识讲完，我用一个真实经历收尾。很多年前，我在一家银行做核心系统维护。某个周五晚上日终跑批结束，总分对账，账不平了。明细账某个科目合计和总账差了360元。360元微不足道，但账不平就是账不平，哪怕差一分钱，也说明账务系统有bug。",-1),m=e("p",null,"那天整个团队留下来排查，从科目缩小到交易类型，再缩小到时间段，查到凌晨两点才定位：一笔批量还款任务，某家渠道接口返回异常，系统重试时把一笔360元的还款记了两遍，主交易是幂等的，但“记账之后的联动动作”漏了幂等。那一夜给了三个教训：第一，账务系统的每个动作都必须幂等；第二，总分对账是账务系统最后、也是最可靠的防线；第三，账务核心的每一行代码都要先回答三个问题，这笔动作幂等吗？出错能冲正吗？对账能发现吗？",-1),x=e("p",null,"到这里，信贷系统最硬核的两块，核心系统与核算引擎，讲完了。下一章，我们把视角从“账”拉回到“决策”：数据怎么驱动信贷决策。",-1);function k(N,q){const t=d("ExternalLinkIcon");return a(),s("div",null,[_,e("blockquote",null,[e("p",null,[n("公众号：侃西东　·　发布日期：2026-11-09　·　"),e("a",l,[n("微信原文"),c(t)])])]),i,h,f,u,b,p,m,x])}const v=o(r,[["render",k],["__file","054.html.vue"]]);export{v as default};
